import GoogleMaps from "@/components/GoogleMaps.vue";
export default {
  components: {
    GoogleMaps
  },
  props: {
    viewGeoLocation: Boolean,
    entryInfo: Object
  },
  data() {
    return {
      mapCenter: {
        lat: 45.508,
        lng: -73.587
      },
      mapMarkers: []
    };
  },
  watch: {
    viewGeoLocation: {
      async handler() {
        if (this.viewGeoLocation == true) {
          if (this.entryInfo.geo_lat != null && this.entryInfo.geo_long != null) {
            const marker = {
              position: {
                lat: Number(this.entryInfo.geo_lat),
                lng: Number(this.entryInfo.geo_long)
              }
            };
            this.mapMarkers = [marker];
            this.mapCenter = marker.position;
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    onMapsLoaded() {
      // Optional: handle map loaded event
    },
    onMarkerClick(marker) {
      this.mapCenter = marker.position;
    }
  }
};
